// Upgrade from every published minor (P8-05): the fixtures (`fixtures/db/v<minor>.json`, generated by
// `scripts/gen-db-fixtures.ts` from the migrations embedded in each release tag) and the checks every SQL adapter runs
// after opening one with the current build. Used on SQLite (`packages/storage-sqlite/test/upgrade.test.ts`) and on D1
// in workerd (`apps/worker/test/d1-upgrade.test.ts`). Web-standard only, so it runs in both.
import { expect } from 'vitest';
import type { Storage } from '../src/index.ts';
import { FIXTURES } from './db-fixtures.generated.ts';

export interface DbFixture {
  readonly minor: string;
  readonly tag: string;
  readonly migrations: readonly {
    readonly version: number;
    readonly name: string;
    readonly checksum: string;
  }[];
  /** Schema, then rows: load in order into an empty database. */
  readonly dump: readonly string[];
}

/**
 * One per published minor. `gen-db-fixtures.ts` writes the list (`db-fixtures.generated.ts`) with every fixture, and the
 * version PR of a new minor adds that minor's fixture (P8-84); the SQLite test checks the list matches the files.
 */
export const DB_FIXTURES: readonly DbFixture[] = FIXTURES;

/** `sqlite_master` rows that make up the schema, comparable across databases (internal and D1 tables left out). */
export const SCHEMA_SQL =
  "SELECT type, name, tbl_name, sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' AND name NOT LIKE '_cf_%' " +
  "AND name NOT LIKE 'd1_%' ORDER BY type, name";

const TOKEN_HASH = 'a'.repeat(64);

/** The seed of `gen-db-fixtures.ts`, read back through the adapter's repositories. */
export async function expectSeededRows(storage: Storage): Promise<void> {
  expect((await storage.users.list()).map((u) => u.id).sort()).toEqual(['usr_member', 'usr_owner']);
  expect(await storage.users.getByEmail('owner@example.com')).toMatchObject({
    id: 'usr_owner',
    role: 'owner',
    idp: 'google',
    idpSubject: 'sub-owner',
    disabledAt: null,
  });
  expect(await storage.users.getByIdentity('google', 'sub-owner')).toMatchObject({ id: 'usr_owner' });

  const shared = await storage.credentials.get('cred_shared');
  expect(shared).toMatchObject({
    ownerUserId: null,
    region: 'US',
    keyHint: 'AB12',
    validationStatus: 'valid',
    nrUserId: 1001,
    reachableAccountIds: [1111111, 2222222],
  });
  const key = shared?.key;
  if (key?.kind !== 'encrypted') throw new Error('expected an encrypted key');
  expect(key.keyVersion).toBe(1);
  expect([...key.iv]).toEqual(Array.from({ length: 12 }, (_, i) => i + 1));
  expect([...key.ciphertext]).toEqual(Array.from({ length: 40 }, (_, i) => (i * 7 + 1) % 256));
  expect(await storage.credentials.list({ ownerUserId: 'usr_member' })).toMatchObject([
    { id: 'cred_member', region: 'EU', validationStatus: 'unvalidated', key: { keyVersion: 2 } },
  ]);

  expect(await storage.projects.getBySlug('main')).toMatchObject({
    id: 'prj_main',
    defaultAccountId: 1111111,
    allowedAccountIds: [1111111, 2222222],
    enabledTools: null,
    limits: { maxLimit: 500, maxWindowDays: 7, eventTypes: { deny: ['Secret'] } },
    defaultCredentialId: 'cred_shared',
  });
  expect(await storage.projects.getBySlug('off')).toMatchObject({
    enabledTools: ['whoami', 'run_nrql'],
    limits: {},
  });
  expect((await storage.projects.getBySlug('off'))?.disabledAt).toBeTypeOf('number');

  expect(await storage.grants.get('gr_member')).toMatchObject({
    projectId: 'prj_main',
    userId: 'usr_member',
    credentialId: 'cred_member',
    tools: ['whoami', 'run_nrql'],
    accountIds: [1111111],
    limits: { maxLimit: 100 },
    rateLimit: { requests: 60, perSeconds: 60 },
    quota: { day: { queries: 100 }, month: { inspectedEvents: 1000000 }, warnPercent: 80 },
  });
  expect(await storage.grants.get('gr_service')).toMatchObject({
    userId: null,
    label: 'ci-bot',
    tools: null,
    rateLimit: null,
    quota: null,
  });

  expect(await storage.accessTokens.getByHash(TOKEN_HASH)).toMatchObject({
    id: 'tok_laptop',
    grantId: 'gr_member',
    prefix: 'rb_abcd',
    revokedAt: null,
  });
  expect((await storage.accessTokens.get('tok_ci'))?.revokedAt).toBeTypeOf('number');

  const audit = await storage.auditLog.list();
  expect(audit.map((r) => [r.id, r.kind, r.action])).toEqual([
    [4, 'tool_call', 'whoami'],
    [3, 'auth', 'auth.denied'],
    [2, 'admin', 'token.revoke'],
    [1, 'tool_call', 'run_nrql'],
  ]);
  expect(audit[0]).toMatchObject({ keyId: 'pt_0123456789ab', accountIds: [1111111] });
  expect(audit[2]).toMatchObject({
    targetType: 'token',
    targetId: 'tok_ci',
    details: { actor: 'admin_token' },
  });

  expect(await storage.settings.get('oauth.registration')).toBe('approval');
  expect(await storage.kv.get('fixture:live')).toBe('{"v":1}');
  expect(await storage.kv.get('fixture:forever')).toBe('plain');
  expect(await storage.grantUsage.get('gr_member', ['d2026-10-01', 'm2026-10'])).toEqual({
    'd2026-10-01': { queries: 3, inspected: 15000 },
    'm2026-10': { queries: 3, inspected: 15000 },
  });

  const records = await storage.loadAccessRecords?.({ tokenHash: TOKEN_HASH, projectSlug: 'main' });
  expect(records).toMatchObject({
    token: { id: 'tok_laptop' },
    project: { id: 'prj_main' },
    grant: { id: 'gr_member' },
    user: { id: 'usr_member' },
    credential: { id: 'cred_member' },
    credentialOwner: null,
  });
}

/** The upgraded database takes new rows next to the old ones (sequences, unique indexes, counters). */
export async function expectWritable(storage: Storage, now: number): Promise<void> {
  const grant = await storage.grants.create({
    id: 'gr_after_upgrade',
    projectId: 'prj_main',
    label: 'after upgrade',
    limits: {},
  });
  expect(grant.projectId).toBe('prj_main');
  await storage.accessTokens.create({
    id: 'tok_after_upgrade',
    grantId: grant.id,
    prefix: 'rb_new',
    tokenHash: 'c'.repeat(64),
    label: 'new',
  });
  expect((await storage.accessTokens.list({ grantId: grant.id })).map((t) => t.id)).toEqual([
    'tok_after_upgrade',
  ]);
  await storage.auditLog.append({ ts: now, kind: 'admin', action: 'grant.create', status: 'ok' });
  expect((await storage.auditLog.list({ limit: 1 }))[0]).toMatchObject({ id: 5, action: 'grant.create' });
  expect(await storage.grantUsage.reserve('gr_member', 'd2026-10-01', 100)).toEqual({
    queries: 4,
    inspected: 15000,
  });
  await storage.settings.set('oauth.registration', 'open');
  expect(await storage.settings.get('oauth.registration')).toBe('open');
}
